SELECT id, symbol, interval_code, candle_open_time, generated_at, created_at, TIMESTAMPDIFF(MICROSECOND, generated_at, created_at)/1000 AS commit_lag_ms, decision, original_decision, atr_immediate_entry_allowed, atr_recommended_position_percent, final_entry_allowed FROM crypto_ai.trade_signal WHERE id IN (156594,156721,156852,156853,159285,159407,165289,165415,166821,167616,167746,168251,172201,172588,176655,176792,176934) ORDER BY id;